WITH product_summary AS (SELECT product_id, MIN(last_restock) AS min_last_restock, AVG(quantity) AS avg_quantity FROM inventory GROUP BY product_id) SELECT p.id, p.launch_date, ps.min_last_restock, ps.avg_quantity FROM products p JOIN product_summary ps ON p.id = ps.product_id WHERE ps.avg_quantity > 180 ORDER BY avg_quantity DESC;
